import ReactDOM from 'react-dom/client'
import QRCode from 'qrcode'
import { BrowserRouter, Link, Navigate, Route, Routes, useNavigate, useParams } from 'react-router-dom'
import { AdminNumberItem, api, apiFile, BuyerReservation, NumberItem, Raffle, Reservation } from './api'
import brandLogo from './assets/rifacil-logo-completo.png'
import './styles.css'
