function ReservationPage(){
  const {code}=useParams(); const [reservation,setReservation]=useState<BuyerReservation|null>(null); const [error,setError]=useState(''); const [message,setMessage]=useState(''); const [remaining,setRemaining]=useState('')
  const [paying,setPaying]=useState(false)
  const load=()=>api<BuyerReservation>(`/reservations/${code}/`).then(setReservation).catch(err=>setError(err.message))
  useEffect(()=>{load()},[code])
  useEffect(()=>{if(!reservation)return;document.body.dataset.reservationMercadopago=reservation.mercadopago_enabled?'enabled':'disabled';return()=>{delete document.body.dataset.reservationMercadopago}},[reservation?.mercadopago_enabled])
  useEffect(()=>{if(!reservation||reservation.status!=='active'){setRemaining('');return}const update=()=>{const seconds=Math.max(0,Math.floor((new Date(reservation.expires_at).getTime()-Date.now())/1000));const minutes=Math.floor(seconds/60);setRemaining(`${minutes}:${String(seconds%60).padStart(2,'0')}`);if(seconds===0)load()};update();const timer=setInterval(update,1000);return()=>clearInterval(timer)},[reservation?.expires_at,reservation?.status])
  const upload=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setError('');try{await api(`/reservations/${code}/receipt/`,{method:'POST',body:new FormData(e.currentTarget)});setMessage('Comprobante enviado correctamente.');await load()}catch(err){setError((err as Error).message)}}
  const cancel=async()=>{if(!window.confirm('¿Cancelar la reserva y liberar los números?'))return;setError('');try{const updated=await api<BuyerReservation>(`/reservations/${code}/cancel/`,{method:'POST'});setReservation(updated);setMessage('La reserva fue cancelada y los números quedaron disponibles.')}catch(err){setError((err as Error).message)}}
  const payWithMercadoPago=async()=>{setError('');setPaying(true);try{const result=await api<{checkout_url:string}>(`/reservations/${code}/mercadopago/`,{method:'POST'});if(!result.checkout_url)throw new Error('No se recibió la URL de pago.');location.assign(result.checkout_url)}catch(err){setError((err as Error).message);setPaying(false)}}
  if(!reservation)return <p>{error||'Cargando…'}</p>
  const active=reservation.status==='active'
  return <section className="buyer-reservation"><span className={`status status--${reservation.status}`}>{reservation.status}</span><h1>{reservation.raffle_title}</h1><p>Código: <code>{reservation.code}</code></p>{active&&<div className="countdown"><span>Tiempo restante</span><strong>{remaining}</strong></div>}<div className="reservation-summary"><div><span>Números</span><strong>{reservation.numbers.join(', ')||'—'}</strong></div><div><span>Total</span><strong>${reservation.total}</strong></div><div><span>Vencimiento</span><strong>{new Date(reservation.expires_at).toLocaleString('es-CL')}</strong></div></div>{active&&<><section className="mercadopago-checkout"><span>Pago online</span><h2>Paga seguro con Mercado Pago</h2><p>Tu reserva se confirmará automáticamente cuando Mercado Pago apruebe el pago.</p><button className="button" onClick={payWithMercadoPago} disabled={paying}>{paying?'Redirigiendo…':'Pagar $'+reservation.total.toLocaleString('es-CL')}</button></section><h2>O paga por transferencia</h2><dl><dt>Banco</dt><dd>{reservation.bank_name||'No informado'}</dd><dt>Tipo de cuenta</dt><dd>{reservation.account_type||'No informado'}</dd><dt>Número de cuenta</dt><dd>{reservation.account_number||'No informado'}</dd><dt>Titular</dt><dd>{reservation.account_holder||'No informado'}</dd><dt>RUT</dt><dd>{reservation.account_holder_id||'No informado'}</dd><dt>Correo</dt><dd>{reservation.transfer_email||'No informado'}</dd></dl><form onSubmit={upload}><label>{reservation.receipt_uploaded?'Reemplazar comprobante':'Subir comprobante'}<input name="receipt" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required /></label><button className="button">Enviar comprobante</button></form><button className="cancel-reservation" onClick={cancel}>Cancelar reserva</button></>}{reservation.status==='confirmed'&&<p className="success">Pago confirmado. Tus números están participando en la rifa.</p>}{reservation.status==='expired'&&<p className="error">Esta reserva venció y los números fueron liberados.</p>}{reservation.status==='cancelled'&&<p>Esta reserva fue cancelada.</p>}{message&&<p className="success">{message}</p>}{error&&<p className="error">{error}</p>}</section>
}

function DrawCountdown({date}:{date:string}){
  const [now,setNow]=useState(Date.now())
  useEffect(()=>{const timer=window.setInterval(()=>setNow(Date.now()),60000);return()=>window.clearInterval(timer)},[])
  const remaining=new Date(date).getTime()-now
  if(remaining<=0)return <small className="draw-countdown">Sorteo pendiente de realización</small>
  const minutes=Math.floor(remaining/60000); const days=Math.floor(minutes/1440); const hours=Math.floor((minutes%1440)/60); const mins=minutes%60
  return <small className="draw-countdown">Faltan {days?`${days}d `:''}{hours}h {mins}min</small>
}

function PublicShare({slug,title}:{slug:string;title:string}){
  const [copied,setCopied]=useState(false); const [qr,setQr]=useState(''); const url=`${location.origin}/rifas/${slug}`
  useEffect(()=>{QRCode.toDataURL(url,{width:170,margin:1,color:{dark:'#06276f',light:'#ffffff'}}).then(setQr)},[url])
  const copy=async()=>{await navigator.clipboard.writeText(url);setCopied(true);setTimeout(()=>setCopied(false),1800)}
  const share=async()=>{if(navigator.share)await navigator.share({title:`Rifa: ${title}`,text:`Participa en ${title}`,url});else await copy()}
  const whatsapp=`https://wa.me/?text=${encodeURIComponent(`¡Participa en ${title}! ${url}`)}`
  return <section className="public-share"><div><strong>¿Conoces a alguien que quiera participar?</strong><span>Comparte esta rifa y ayúdanos a llegar a la meta.</span><div><a href={whatsapp} target="_blank" rel="noreferrer">WhatsApp</a><button type="button" onClick={share}>Compartir</button><button type="button" onClick={copy}>{copied?'¡Copiado!':'Copiar enlace'}</button></div></div>{qr&&<div className="public-qr"><img src={qr} alt={`Código QR para compartir ${title}`}/><a href={qr} download={`qr-${slug}.png`}>Descargar QR</a></div>}</section>
}

function Detail(){
  const {slug}=useParams(); const nav=useNavigate(); const [raffle,setRaffle]=useState<Raffle|null>(null); const [selected,setSelected]=useState<number[]>([]); const [error,setError]=useState('')
  const [numberEntry,setNumberEntry]=useState(''); const [numberEntryMessage,setNumberEntryMessage]=useState('')
  useEffect(()=>{api<Raffle>(`/raffles/${slug}/`).then(setRaffle).catch(err=>setError(err.message))},[slug])
  if(!raffle)return <p className="loading-state">{error||'Cargando rifa…'}</p>
  const toggle=(number:number)=>setSelected(current=>current.includes(number)?current.filter(item=>item!==number):current.length<20?[...current,number]:current)
  const addWrittenNumbers=()=>{
    const requested=[...new Set(numberEntry.split(',').map(value=>value.trim()).filter(Boolean).map(Number).filter(Number.isInteger))]
    const available=new Set(raffle.numbers.filter(item=>item.status==='available').map(item=>item.number))
    const accepted=requested.filter(number=>available.has(number))
    const rejected=requested.filter(number=>!available.has(number))
    setSelected(current=>[...new Set([...current,...accepted])].slice(0,20).sort((a,b)=>a-b))
    setNumberEntry('')
    setNumberEntryMessage(rejected.length?`No disponibles o inválidos: ${rejected.join(', ')}`:accepted.length?'Números agregados a tu selección.':'Escribe números separados por comas.')
  }
  const reserve=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setError('');const buyer=Object.fromEntries(new FormData(e.currentTarget));try{const result=await api<{code:string}>(`/raffles/${slug}/reserve/`,{method:'POST',body:JSON.stringify({...buyer,numbers:selected})});localStorage.setItem('lastReservationCode',result.code);nav(`/reserva/${result.code}`)}catch(err){setError((err as Error).message)}}
  const percentage=raffle.total_numbers?(raffle.sold_count/raffle.total_numbers)*100:0
  return <div className="public-raffle" style={{'--raffle-accent':raffle.accent_color} as React.CSSProperties}>
    <section className="public-cover">{raffle.cover_url?<img src={raffle.cover_url} alt={`Portada de ${raffle.title}`}/>:<div className="cover-placeholder">{raffle.title.charAt(0)}</div>}<div className="cover-gradient"/><div className="public-title"><span className={`state state--${raffle.status}`}>{raffle.status}</span><h1>{raffle.title}</h1><p>Organiza {raffle.owner.username}</p></div></section>
    {raffle.winning_number!==null&&<section className="winner-public"><span>🎉 Número ganador</span><strong>{raffle.winning_number}</strong><small>Sorteado el {new Date(raffle.drawn_at!).toLocaleString('es-CL')}</small></section>}
    <div className="public-summary"><div><span>Premio</span><strong>{raffle.prize}</strong></div><div><span>Valor por número</span><strong>${raffle.number_price.toLocaleString('es-CL')}</strong></div><div><span>Fecha del sorteo</span><strong>{raffle.draw_date?new Date(raffle.draw_date).toLocaleDateString('es-CL'):'Por confirmar'}</strong>{raffle.draw_date&&<DrawCountdown date={raffle.draw_date}/>}</div></div>
    <PublicShare slug={raffle.slug} title={raffle.title}/><section className="public-description"><div><h2>Sobre esta rifa</h2><p>{raffle.description}</p>{raffle.terms&&<div className="raffle-terms"><h3>Bases y condiciones</h3><p>{raffle.terms}</p></div>}</div><div className="sales-progress"><div><span>Progreso</span><strong>{raffle.sold_count} de {raffle.total_numbers} vendidos</strong></div><div className="progress"><span style={{width:`${percentage}%`}}/></div>{raffle.fundraising_goal&&<div className="fundraising-progress"><div><span>Meta de recaudación</span><strong>${raffle.sold_revenue.toLocaleString('es-CL')} de ${raffle.fundraising_goal.toLocaleString('es-CL')}</strong></div><div className="progress"><span style={{width:`${Math.min(100,(raffle.sold_revenue/raffle.fundraising_goal)*100)}%`}}/></div></div>}</div></section>
    {raffle.status==='published'?<div className="selection-layout">
      <main className="number-panel"><div className="number-heading"><div><span className="admin-kicker">Paso 1</span><h2>Elige tus números</h2></div><span>Puedes elegir hasta 20</span></div><div className="number-legend"><span><i className="available-dot"/>Disponible</span><span><i className="selected-dot"/>Seleccionado</span><span><i className="occupied-dot"/>Ocupado</span></div><div className="numbers modern-numbers">{raffle.numbers.map(item=><button type="button" aria-pressed={selected.includes(item.number)} className={`${selected.includes(item.number)?'selected ':''}number--${item.status}`} onClick={()=>toggle(item.number)} key={item.id} disabled={item.status!=='available'}>{item.number}</button>)}</div></main>
      <aside className="selection-card"><span className="admin-kicker">Paso 2</span><h2>Tu selección</h2><div className="quick-number-entry"><label htmlFor="number-entry">Escribe tus números separados por comas</label><div><input id="number-entry" value={numberEntry} onChange={event=>{setNumberEntry(event.target.value);setNumberEntryMessage('')}} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();addWrittenNumbers()}}} inputMode="numeric" placeholder="Ej: 3, 8, 15, 24"/><button type="button" onClick={addWrittenNumbers}>Agregar</button></div>{numberEntryMessage&&<small>{numberEntryMessage}</small>}</div>{selected.length?<div className="selected-chips">{selected.map(number=><button type="button" key={number} onClick={()=>toggle(number)}>{number} ×</button>)}</div>:<p className="muted">Selecciona uno o más números del tablero.</p>}<div className="selection-total"><span>{selected.length} {selected.length===1?'número':'números'}</span><strong>${(selected.length*raffle.number_price).toLocaleString('es-CL')}</strong></div>{error&&<p className="error">{error}</p>}<form onSubmit={reserve}><label>Tu nombre<input name="buyer_name" required/></label><label>Correo electrónico<input name="buyer_email" type="email" required/></label><label>Teléfono {raffle.phone_required?'':'(opcional)'}<input name="buyer_phone" type="tel" inputMode="tel" autoComplete="tel" required={raffle.phone_required} placeholder="Ej: +56 9 1234 5678"/></label><button className="button coral" disabled={!selected.length}>Reservar por 20 minutos</button></form></aside>
    </div>:raffle.winning_number===null&&<section className="closed-notice"><h2>Esta rifa está cerrada</h2><p>Ya no se aceptan nuevas reservas.</p></section>}
  </div>
}

function App(){return <BrowserRouter><Layout><Routes><Route path="/" element={<Home/>}/><Route path="/planes" element={<Pricing/>}/><Route path="/ayuda/pro" element={<ProHelp/>}/><Route path="/administracion" element={<AdministrationRoute/>}/><Route path="/administracion/rifas/:slug" element={<AdministrationRaffle/>}/><Route path="/administracion/:section" element={<AdministrationRoute/>}/><Route path="/ingresar" element={<Auth/>}/><Route path="/registro" element={<Auth register/>}/><Route path="/panel" element={<Dashboard/>}/><Route path="/panel/rifas/:slug" element={<RaffleAdminPage/>}/><Route path="/nueva" element={<Create/>}/><Route path="/reserva" element={<ReservationLookup/>}/><Route path="/reserva/:code" element={<ReservationPage/>}/><Route path="/rifas/:slug/editar" element={<Edit/>}/><Route path="/rifas/:slug" element={<Detail/>}/></Routes></Layout></BrowserRouter>}
ReactDOM.createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>)
